from research_helpers import *
a=ev('https://www.transcodetherapeutics.com/pipeline.html','Current public pipeline names TTX-MC138, TTX-siPDL1, TTX-RIGA and TTX-siMYC; all investigational.')
b=ev('https://www.transcodetherapeutics.com/','Current issuer confirms Phase 2a initiation of lead TTX-MC138 in June 2026.')
c=ev('https://www.sec.gov/Archives/edgar/data/1829635/000182963526000003/rnaz-20260630x10q.htm','Current filing confirms completed Polynoma acquisition and acquired Seviprotimut-L investigational melanoma vaccine.')
d=ev('https://www.transcodetherapeutics.com/uploads/1/7/4/2/17421591/partnership_opportunities.pdf','Issuer partnering sheet names TTX-mRNA, TTX-CRISPR, TCD-miR-10b, R-TTX-z and TBS nanobody scaffold; broad product-line umbrellas not separate candidates.')
products=[p('TTX-MC138','MicroRNA-10b-directed metastatic-cancer candidate.',a,'development',evidence=[a,b])]
for name,desc in [('TTX-siPDL1','siRNA-based PD-L1 modulator.'),('TTX-RIGA','RNA-based RIG-I agonist.'),('TTX-siMYC','siRNA-based c-MYC inhibitor.')]:products.append(p(name,desc,a,'research'))
products.append(p('Seviprotimut-L','Investigational polyvalent melanoma vaccine acquired through Polynoma.',c,'development',roles=['commercial_partner']))
for name,desc,sub,typ in [('TTX-mRNA','Cancer-vaccine development programme.','therapeutics','development_program'),('TTX-CRISPR','Gene-editing development programme.','therapeutics','development_program'),('TCD-miR-10b','Early-cancer molecular-diagnostic programme.','diagnostics','development_program'),('R-TTX-z','Targeted radiotherapy development programme.','therapeutics','development_program'),('TransCode TBS nanobody scaffold','Target-binding-scaffold technology.','therapeutics','technology')]:products.append(p(name,desc,d,typ=typ,sub=sub))
co=dict(company_id='cmp_1d5f5c29-95db-41cc-982d-f2a6c558670a',products=products,evidence=[a,b,c,d],status='partial',coverage_note='Ten explicitly named therapeutic/diagnostic programmes and scaffold technology recorded. Partial: current legacy partnering programmes, 64Cu-TTX-MC138 and TTX-siLIN28b option-to-licence status, and exact Polynoma subsidiary rights need review. Option-to-negotiate not automatically licence ownership. Seviprotimut-L distinct from RNA candidates; prior Phase 3 study completion not marketing approval. Natera Signatera used for trial selection not attributed as TransCode-developed diagnostic.')
(out/'batch-0259.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
